using Microsoft.Data.SqlClient;

public static class ProductQueries
{
    static string Escape(string s) => s.Replace("'", "''");

    public static SqlCommand ByCategory(SqlConnection db, string categoryId) =>
        new($"""
            SELECT Name, Price FROM Products
            WHERE IsPublished = 1 AND CategoryId = {Escape(categoryId)}
            """, db);
}

using System.Data;
using Microsoft.Data.SqlClient;

public static class ProductQueries
{
    public static SqlCommand ByCategory(SqlConnection db, int categoryId)
    {
        var cmd = new SqlCommand("""
            SELECT Name, Price FROM Products
            WHERE IsPublished = 1 AND CategoryId = @categoryId
            """, db);
        cmd.Parameters.Add("@categoryId", SqlDbType.Int).Value = categoryId;
        return cmd;
    }
}

using Microsoft.EntityFrameworkCore;

public static class ProductQueries
{
    // FromSql turns {categoryId} into a parameter; FromSqlRaw would not
    public static IQueryable<Product> ByCategory(ShopDb db, int categoryId) =>
        db.Products.FromSql($"""
            SELECT * FROM Products
            WHERE IsPublished = 1 AND CategoryId = {categoryId}
            """);
}
